import React, { useState, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);

  useEffect(() => {
    const loader = new OBJLoader();

    loader.load(
      modelPath, // Path to the OBJ file
      (obj) => {
        console.log('Model loaded:', obj); // Debugging log
        obj.scale.set(0.1, 0.1, 0.1); // Scale the model to ensure it's visible
        obj.position.set(0, 0, 0); // Ensure it's at the center
        obj.traverse((child) => {
          if (child.isMesh) {
            // Set white wireframe material
            child.material = new THREE.MeshBasicMaterial({
              color: 0xffffff, // White color for the wireframe
              wireframe: true, // Enable wireframe rendering
            });
          }
        });
        setModel(obj); // Set the loaded model
      },
      undefined, // Optional progress callback
      (error) => {
        console.error('Error loading OBJ:', error); // Error handling
      }
    );
  }, [modelPath]);

  // If the model is loaded, return it with wireframe material; otherwise, show a placeholder cube
  return model ? (
    <primitive object={model} />
  ) : (
    <mesh>
      <boxGeometry args={[1, 1, 1]} />
      <meshBasicMaterial color="white" wireframe={true} />
    </mesh>
  );
};

const App = () => {
  // Path to the model (from the src/stls folder)
  const modelPath = require('./stls/model.obj'); // Import the model from the stls folder

  return (
    <div style={{ height: '100vh', margin: 0 }}>
      <h1 style={{ position: 'absolute', color: 'white', top: '10px', left: '10px' }}>
        3D Model Viewer
      </h1>
      {/* Canvas is the 3D scene container */}
      <Canvas
        style={{ backgroundColor: 'black' }} // Set the background to black
        camera={{ position: [0, 0, 5], fov: 75 }} // Initial camera setup
      >
        {/* Lights */}
        <ambientLight intensity={0.5} /> {/* Ambient light for general lighting */}
        <spotLight position={[10, 10, 10]} intensity={1} /> {/* Spot light for more focused lighting */}
        <directionalLight position={[5, 5, 5]} intensity={1} /> {/* Directional light for strong illumination */}

        {/* Model loader */}
        <ModelLoader modelPath={modelPath} />

        {/* Orbit controls for camera movement (with no zooming) */}
        <OrbitControls enableZoom={false} />
      </Canvas>
    </div>
  );
};

export default App;
